function browseOptions(){const sort={newest:'الأحدث أولًا',oldest:'الأقدم أولًا',amount:recordResource==='stock'?'الأكبر كمية':'الأكبر مبلغًا'},warehouse=Object.fromEntries(['all',...S.warehouses].map(w=>[w,w==='all'?'كل المخازن':w])),bankaccount=Object.fromEntries([['all','كل الحسابات'],...S.accounts.filter(a=>!a.archived).map(a=>[String(a.id),a.name])]);return {resource:{title:'نوع السجل',value:recordResource,options:browseResources},period:{title:'الفترة',value:period,options:{today:'اليوم',all:'كل الفترة',custom:'فترة مخصصة'}},kind:{title:'نوع المستند',value:filter,options:browseKinds},sort:{title:'ترتيب السجل',value:recordSort,options:sort},bank:{title:'قسم الحسابات',value:accountsTab,options:browseBanks},bankaccount:{title:'الحساب',value:bankAccountFilter,options:bankaccount},warehouse:{title:'المخزن',value:auditScope,options:warehouse},report:{title:'نوع التقرير',value:reportType,options:browseReports}}[browsePicker]}
