recordRow=function(r){const out=['purchase','expense','pay','withdraw'].includes(r.kind),neutral=['transfer','stocktransfer','adjustment','offset'].includes(r.kind),state=r.voided?'ملغاة':r.due?'ملاحظة على الحساب':neutral?'معتمدة':'مدفوعة بالكامل';return `<button class="invoice-register-row record-card" data-action="invoice:${r.id}"><span class="document-heading"><b>${documentLabels[r.kind]||r.kind}</b><span class="document-status">${state}</span></span><span class="document-data"><span><small>${['expense','deposit','withdraw'].includes(r.kind)?'البيان':'الطرف / البيان'}</small><strong>${esc(r.title)}</strong></span><span class="document-total"><small>المبلغ</small>${money(r.total,'sm',neutral?'':out?'negative':'positive')}</span></span><span class="document-footer"><span><small>المستند</small><b dir="ltr">${r.kind.toUpperCase()}-${r.id}</b></span><span><small>التاريخ</small><b dir="ltr">${r.date||'2026-10-04'} · ${r.time}</b></span></span></button>`};
