// Review 13: actual tabular registers, matching the desktop fields.
function table13(headers,body,label){return `<div class="register-table-shell"><div class="register-scroll" tabindex="0" role="region" aria-label="${label}"><table class="register-table" aria-label="${label}"><thead><tr>${headers.map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div></div>`}
function recordActions13(r){return r.voided?`<button class="table-open" data-action="invoice:${r.id}">عرض</button>`:`<div class="table-actions"><button data-action="source:${r.id}" aria-label="تعديل ${r.kind.toUpperCase()}-${r.id}">تعديل</button><button class="table-delete" data-action="void:${r.id}" aria-label="حذف ${r.kind.toUpperCase()}-${r.id}">حذف</button></div>`}
function recordDate13(r){return `<span class="table-date" dir="ltr">${r.date||'2026-10-04'}<small>${r.time}</small></span>`}
function documentCell13(r){return `<button class="table-document" data-action="invoice:${r.id}" dir="ltr">${r.kind.toUpperCase()}-${r.id}</button>`}
rows=function(list,desc='لا توجد عمليات في هذه الفترة'){if(!list.length)return empty(desc,'ستظهر الفواتير والحركات هنا بعد تسجيلها.');const transfers=list.every(r=>r.kind==='stocktransfer'),adjustments=list.every(r=>r.kind==='adjustment');const headers=transfers?['التاريخ','المستند','من','إلى','الكمية','إجراءات']:adjustments?['التاريخ','المستند','المنتج','المخزن','قبل','بعد','إجراءات']:['التاريخ','المستند','النوع','الطرف / البيان','الحالة','المبلغ','إجراءات'];return table13(headers,list.map(r=>{const out=['purchase','expense','pay','withdraw'].includes(r.kind),neutral=['transfer','stocktransfer','adjustment','offset'].includes(r.kind),state=r.voided?'ملغاة':r.due?'ملاحظة':neutral?'معتمدة':'مدفوعة';let cells=transfers?`<td>${esc(r.from)}</td><td>${esc(r.toWarehouse)}</td><td class="table-number">${(r.lines||[]).reduce((n,l)=>n+l.qty,0)}</td>`:adjustments?`<td>${esc(r.title)}</td><td>${esc(r.warehouse)}</td><td class="table-number">${r.newQty-(r.lines?.[0]?.delta||0)}</td><td class="table-number">${r.newQty}</td>`:`<td>${documentLabels[r.kind]||r.kind}</td><td class="table-party">${esc(r.title)}</td><td>${state}</td><td class="table-number">${money(r.total,'xs',neutral?'':out?'negative':'positive')}</td>`;return `<tr><td>${recordDate13(r)}</td><td>${documentCell13(r)}</td>${cells}<td>${recordActions13(r)}</td></tr>`}).join(''),transfers?'سجل تحويلات المخزون':adjustments?'سجل تصحيح المخزون':'سجل المستندات')};
function movementTable13(list,resource){const stock=resource==='stock',headers=stock?['التاريخ','المستند','العملية','المنتج / المخزن','قبل','التغيير','بعد','إجراءات']:['التاريخ','المستند','النوع','الحساب','الطرف','الحركة','المبلغ','إجراءات'];return table13(headers,list.map(x=>{const party=S.parties.find(p=>p.id===x.r.party)?.name||'—',cells=stock?`<td class="table-party">${esc(x.label)}</td><td class="table-number">${x.before}</td><td class="table-number ${x.delta>0?'positive':'negative'}">${x.delta>0?'+':''}${x.delta}</td><td class="table-number">${x.after}</td>`:`<td>${esc(x.label)}</td><td class="table-party">${esc(party)}</td><td>${x.delta>0?'داخل':'خارج'}</td><td class="table-number">${money(x.amount,'xs',x.delta>0?'positive':'negative')}</td>`;return `<tr><td>${recordDate13(x.r)}</td><td>${documentCell13(x.r)}</td><td>${documentLabels[x.r.kind]}</td>${cells}<td>${recordActions13(x.r)}</td></tr>`}).join(''),stock?'سجل حركة المخزون':'سجل الحركة المالية')}



// Review 16: only the home page's recent invoices get four fitted columns.
