function posModal(title,body,action='',label='حفظ'){return `<div class="overlay"><section class="sheet pos-sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-handle"></div><div class="sheet-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="إغلاق">${icon('close')}</button></div><div class="sheet-body"><form id="sheet-form">${body}</form><div id="form-error"></div></div>${action?primary(label,action):''}</section></div>`}
cartTotal=()=>posRound(cart.reduce((sum,l)=>sum+posRound(l.qty*l.price),0));
function posProducts(query=posQuery){const q=query.trim().toLocaleLowerCase(),frequency=new Map();if(!q)for(const r of liveRecords())if(r.kind==='sale')for(const l of r.lines||[])frequency.set(l.product,(frequency.get(l.product)||0)+l.qty);return S.products.filter(p=>!p.archived&&(!q||searchMatches(p.name+' '+p.sku,q))).sort((a,b)=>q?0:(frequency.get(b.id)||0)-(frequency.get(a.id)||0))}
function posProductResults(query,limit=posLimit){const all=posProducts(query),list=all.slice(0,limit);return `<div class="pos-product-results">${list.map((p,i)=>{const unavailable=saleType==='sale'&&(posExpired(p)||posAvailable(p)<=0),count=cart.find(l=>l.id===p.id)?.qty||0;return `<button type="button" class="pos-product-hit" data-action="pos:add:${p.id}" ${unavailable?'disabled':''} aria-label="إضافة ${esc(p.name)}"><span class="pos-result-number">${i+1}</span><span class="pos-result-copy"><strong>${esc(p.name)}</strong><small class="${unavailable?'negative':''}">${saleType==='sale'&&posExpired(p)?'منتهي الصلاحية':`متوفر ${posAvailable(p)}${p.sku?' · '+esc(p.sku):''}`}${count?' · في الفاتورة '+count:''}</small></span><span class="pos-result-price">${money(posUnitPrice(p),'xs')}</span><span class="pos-result-add">${icon('plus')}</span></button>`}).join('')||`<div class="pos-no-results"><strong>${S.products.length?'لا توجد نتائج':'لا توجد منتجات بعد'}</strong><p>${S.products.length?'جرّب الاسم أو الباركود.':'أضف أول منتج لبدء الفاتورة.'}</p></div>`}</div>${all.length>limit?`<button type="button" class="pos-more" data-action="pos:more">عرض المزيد · ${list.length} من ${all.length}</button>`:''}`}
function posCartMarkup(){return `<div class="register-table-shell pos-cart-table-frame"><table class="pos-cart-table" aria-label="بنود الفاتورة"><colgroup><col style="width:40%"><col style="width:22%"><col style="width:14%"><col style="width:24%"></colgroup><thead><tr><th scope="col">المنتج</th><th scope="col">السعر</th><th scope="col">الكمية</th><th scope="col">المجموع</th></tr></thead><tbody>${cart.map((l,i)=>{const p=S.products.find(p=>p.id===l.id),below=saleType==='sale'&&l.price<posCost(p);return `<tr><td><div class="pos-table-product"><button type="button" class="pos-table-name" data-action="pos:line:${p.id}" aria-label="تعديل ${esc(p.name)}"><small>${i+1}</small><strong>${esc(p.name)}</strong></button><button type="button" class="pos-table-remove" data-action="pos:remove:${p.id}" aria-label="إزالة ${esc(p.name)}">${icon('close')}</button></div>${below?'<small class="pos-table-warning">السعر أقل من تكلفة الشراء</small>':''}</td><td><button type="button" class="pos-table-value" data-action="pos:line:${p.id}" aria-label="تعديل سعر ${esc(p.name)}">${money(l.price,'xs')}</button></td><td><button type="button" class="pos-table-value" data-action="pos:line:${p.id}" aria-label="تعديل كمية ${esc(p.name)}">${l.qty}</button></td><td>${money(posRound(l.qty*l.price),'xs')}</td></tr>`}).join('')}</tbody></table></div>`}

sale=function(){const party=S.parties.find(p=>p.id===S.saleParty);return `<div class="pos-workspace"><div class="pos-context"><button data-action="pos:party"><span>${saleType==='purchase'?'المورد':'العميل'}</span><strong>${esc(party?.name||(saleType==='sale'?'بيع مباشر':'اختيار المورد'))}</strong>${icon('people')}</button><button data-action="pos:warehouse" ${editingId?'disabled title="مخزن الفاتورة الأصلية"':''}><span>المخزن</span><strong>${esc(S.warehouse)}</strong>${icon('warehouse')}</button></div>${editingId?`<div class="pos-editing">تعديل ${esc(posOld()?.number||saleType.toUpperCase()+'-'+editingId)}</div>`:''}<div class="pos-discovery"><label class="pos-search">${icon('search')}<input id="pos-search" type="search" value="${esc(posQuery)}" placeholder="اسم المنتج أو الباركود" aria-label="اسم المنتج أو الباركود" autocomplete="off"><button type="button" data-action="pos:barcode" aria-label="إدخال باركود">${icon('scan')}</button></label><div id="pos-search-results">${posQuery?posProductResults(posQuery):''}</div></div><div class="pos-cart-heading">${posHeading('بنود الفاتورة',`<button data-action="pos:products">${icon('plus')}إضافة منتجات</button>`)}</div>${cart.length?'<button class="pos-clear" data-action="pos:clear">تفريغ البنود</button>':''}<div id="pos-error"></div><div class="pos-cart">${cart.length?posCartMarkup():`<div class="pos-empty"><span>${icon(saleType==='sale'?'cart':'purchase')}</span><strong>ابدأ فاتورتك</strong><p>ابحث عن المنتج أو افتح المنتجات لإضافته.</p><button data-action="pos:products">${icon('plus')}اختيار منتجات</button></div>`}</div>${cart.length?`<button class="pos-note-button" data-action="pos:note">${icon('edit')}${posNote?'تعديل ملاحظة الفاتورة':'إضافة ملاحظة للفاتورة'}</button>`:''}</div>`};
footer=function(){if(['sale','purchase'].includes(view))return `<div class="sticky pos-checkout-bar"><div><small>${cart.length} أصناف · ${cart.reduce((n,l)=>n+l.qty,0)} وحدات</small><div class="pos-checkout-total"><span>الإجمالي</span>${money(posRound(cartTotal()),'sm')}</div></div><button class="primary" data-action="pos:checkout" ${!cart.length?'disabled':''}>${editingId?'مراجعة التعديل':'متابعة للدفع'}${icon('arrow')}</button></div>`;return posPreviousFooter()};
function posPaymentMarkup(){const party=S.parties.find(p=>p.id===S.saleParty),accounts=S.accounts.filter(a=>!a.archived);return posModal(editingId?'مراجعة تعديل الفاتورة':saleType==='sale'?'إتمام البيع':'إتمام الشراء',`<div class="pos-payment-total"><span>إجمالي الفاتورة</span>${money(posRound(cartTotal()),'lg')}<small>${cart.length} أصناف · ${cart.reduce((n,l)=>n+l.qty,0)} وحدات</small></div><div class="pos-payment-modes"><button type="button" data-action="pos:settlement:paid" aria-pressed="${settlement==='paid'}">${icon('wallet')}دفع مباشر<small>كامل المبلغ</small></button><button type="button" data-action="pos:settlement:note" aria-pressed="${settlement==='note'}">${icon('edit')}ملاحظة<small>على حساب الطرف</small></button></div><div class="pos-payment-context"><button type="button" data-action="pos:party"><span>${saleType==='sale'?'العميل':'المورد'}${settlement==='note'?' · مطلوب':''}</span><strong>${esc(party?.name||(settlement==='note'?'اختيار الطرف':saleType==='sale'?'بيع مباشر':'شراء نقدي'))}</strong>${icon('arrow')}</button></div>${settlement==='paid'?`<label class="field"><span>وسيلة الدفع</span><select name="account" aria-label="وسيلة الدفع">${accounts.map(a=>`<option value="${a.id}" ${a.id===paymentAccount?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`:`<p class="pos-payment-note">كامل قيمة الفاتورة ملاحظة على حساب الطرف. لا توجد حركة نقدية.</p>`}<div class="pos-payment-review"><span>المخزن</span><strong>${esc(S.warehouse)}</strong></div>${posNote?`<p class="pos-payment-note">${esc(posNote)}</p>`:''}`,settlement==='note'&&!party?'pos:party':'post-sale',settlement==='note'&&!party?'اختيار الطرف لإتمام الفاتورة':editingId?'حفظ تعديل الفاتورة':saleType==='sale'?'تأكيد البيع':'تأكيد الشراء')}
let posReturnToPayment=false;
sheet=function(){if(modal==='payment'&&['sale','purchase'].includes(view))return posPaymentMarkup();if(modal==='pos-recent')return posModal('الفواتير الأخيرة',`<div class="pos-choice-list">${liveRecords().filter(r=>r.kind===saleType).slice(0,15).map(r=>`<button type="button" data-action="invoice:${r.id}"><span><strong>${esc(r.title)}</strong><small>${esc(r.date||'')} · ${esc(r.number||r.kind.toUpperCase()+'-'+r.id)}</small></span>${money(r.total,'xs')}</button>`).join('')||'<p class="pos-payment-note">لا توجد فواتير بعد.</p>'}</div>`);if(modal==='pos-products')return posModal('اختيار المنتجات',`<label class="pos-search">${icon('search')}<input id="pos-picker-search" type="search" value="${esc(posQuery)}" placeholder="اسم المنتج أو الباركود" aria-label="بحث المنتجات" autocomplete="off"></label><div id="pos-picker-results">${posProductResults(posQuery)}</div><button type="button" class="pos-new-product" data-action="open:product">${icon('plus')}إضافة منتج جديد</button>`);
if(modal==='pos-party'){const type=saleType==='sale'?'customer':'supplier',list=S.parties.filter(p=>p.type===type&&!p.archived&&searchMatches(p.name+' '+p.phone,posPartyQuery));return posModal(type==='customer'?'اختيار العميل':'اختيار المورد',`<label class="pos-search">${icon('search')}<input id="pos-party-search" type="search" value="${esc(posPartyQuery)}" placeholder="الاسم أو الهاتف" aria-label="الاسم أو الهاتف"></label><div id="pos-party-results">${posPartyResults(list)}</div><button type="button" class="pos-new-product" data-action="pos:new-party">${icon('plus')}${type==='customer'?'إضافة عميل':'إضافة مورد'}</button>`)}
if(modal==='pos-new-party')return posModal(saleType==='sale'?'إضافة عميل':'إضافة مورد',field('الاسم',input('name'))+field('الهاتف · اختياري',input('phone','tel')),'pos:save-party','حفظ واختيار');
if(modal==='pos-warehouse')return posModal('اختيار المخزن',`<div class="pos-choice-list">${S.warehouses.map(w=>`<button type="button" data-action="pos:warehouse-pick:${esc(w)}" aria-pressed="${w===S.warehouse}">${icon('warehouse')}<strong>${esc(w)}</strong>${w===S.warehouse?icon('check'):''}</button>`).join('')}</div>`);
if(modal==='pos-line'){const l=cart.find(l=>l.id===posEditingLine),p=S.products.find(p=>p.id===posEditingLine);return posModal('تعديل بند الفاتورة',`<p class="pos-edit-product">${esc(p.name)}</p><div class="pair">${field('الكمية',posNumberInput('quantity',l.qty))}${field('سعر الوحدة',posNumberInput('price',l.price))}</div>${saleType==='sale'?`<p class="pos-payment-note">متوفر في المخزن: ${posAvailable(p)} وحدة</p>`:''}`,'pos:save-line')}
if(modal==='pos-barcode')return posModal('إدخال باركود',field('الباركود أو رمز المنتج',input('code')),'pos:find-barcode','إضافة إلى الفاتورة');
if(modal==='pos-note')return posModal('ملاحظة الفاتورة',field('الملاحظة',`<textarea name="note" rows="3">${esc(posNote)}</textarea>`),'pos:save-note');
if(modal==='pos-clear')return posModal('تفريغ الفاتورة','<p class="pos-payment-note">ستُزال البنود من المسودة الحالية. لا يتغيّر أي مستند مسجّل.</p>','pos:confirm-clear','تفريغ المسودة');
if(modal==='pos-leave')return posModal('الفاتورة لم تُحفظ',`<p class="pos-payment-note">${['new','source'].includes(posPendingNavigation?.split(':')[0])?'فتح فاتورة أخرى يمسح بنود المسودة الحالية.':'يمكنك مغادرة الصفحة مع الاحتفاظ بمسودتك، أو متابعة الفاتورة الحالية.'}</p><button type="button" class="pos-more" data-action="close">متابعة الفاتورة</button>`,'pos:confirm-leave',['new','source'].includes(posPendingNavigation?.split(':')[0])?'فتح الفاتورة الأخرى':'مغادرة مع حفظ المسودة');
if(modal==='pos-below-cost'){const lines=cart.filter(l=>l.price<posCost(S.products.find(p=>p.id===l.id)));return posModal('تنبيه البيع بأقل من التكلفة',`<p class="pos-payment-note">هذه البنود بسعر أقل من تكلفة الشراء. راجعها قبل اعتماد البيع.</p><div class="pos-cost-warning">${lines.map(l=>`<p><strong>${esc(S.products.find(p=>p.id===l.id).name)}</strong><span>سعر البيع ${l.price} · التكلفة ${posCost(S.products.find(p=>p.id===l.id))} MRU</span></p>`).join('')}</div>`,'pos:confirm-below-cost','اعتماد البيع بهذا السعر')}
return posPreviousSheet()};
function posPartyResults(list){return `<div class="pos-choice-list">${settlement==='paid'?`<button type="button" data-action="pos:party-pick:0"><strong>${saleType==='sale'?'بيع مباشر دون عميل':'شراء نقدي دون مورد'}</strong></button>`:''}${list.slice(0,50).map((p,i)=>`<button type="button" data-action="pos:party-pick:${p.id}"><span class="pos-result-number">${i+1}</span><span><strong>${esc(p.name)}</strong>${p.phone?`<small dir="ltr">${esc(p.phone)}</small>`:''}</span>${p.id===S.saleParty?icon('check'):''}</button>`).join('')||'<p class="pos-payment-note">لا توجد أطراف مطابقة. يمكنك إضافة طرف جديد.</p>'}${list.length>50?'<p class="pos-payment-note">اكتب الاسم أو الهاتف لتحديد الطرف المطلوب.</p>':''}</div>`}
function posCheckLine(p,qty){if(!p||p.archived&&!posOld()?.lines.some(l=>l.product===p.id))return 'المنتج غير متاح';if(!Number.isFinite(qty)||qty<=0)return 'أدخل كمية صحيحة أكبر من صفر';if(saleType==='sale'&&posExpired(p))return 'انتهت صلاحية هذا المنتج ولا يمكن بيعه';if(saleType==='sale'&&qty>posAvailable(p))return `المتوفر من ${p.name}: ${posAvailable(p)} وحدة فقط`;return ''}
function posAdd(id){const keepFocus=document.activeElement?.id==='pos-search';const p=S.products.find(p=>p.id===Number(id)),l=cart.find(l=>l.id===p?.id),qty=(l?.qty||0)+1,problem=posCheckLine(p,qty);if(problem)return posMessage(problem);if(l)l.qty=qty;else cart.unshift({id:p.id,qty:1,price:posUnitPrice(p)});posQuery='';posLimit=20;modal=null;render();if(keepFocus)document.querySelector('#pos-search')?.focus();toast('أُضيف '+p.name)}
sourceDocument=function(id){const r=S.records.find(r=>r.id===Number(id));if(r&&['sale','purchase'].includes(r.kind)&&!r.voided){if(cart.length){posPendingNavigation='source:'+id;modal='pos-leave';return render()}posMode=r.pricingMode||'retail';posNote=r.note||'';posQuery='';posBelowApproved=''}return posPreviousSource(id)};
newRecord=function(kind){const r=posPreviousRecord(kind);if(['sale','purchase'].includes(kind)){r.pricingMode=posMode;r.note=posNote}return r};
postSale=function(){for(const l of cart){const p=S.products.find(p=>p.id===l.id),problem=posCheckLine(p,l.qty);if(problem)return posMessage(problem);if(!Number.isFinite(l.price)||l.price<=0)return posMessage('أدخل سعرًا صحيحًا أكبر من صفر')}if(!cart.length)return posMessage('أضف منتجًا إلى الفاتورة');const f=form();if(f.party)S.saleParty=Number(f.party);if(f.account)paymentAccount=Number(f.account);if(settlement==='note'&&!S.parties.some(p=>p.id===S.saleParty&&!p.archived&&p.type===(saleType==='sale'?'customer':'supplier')))return posMessage('اختر الطرف لتسجيل الملاحظة');if(settlement==='paid'&&!S.accounts.some(a=>a.id===paymentAccount&&!a.archived))return posMessage('اختر وسيلة دفع فعالة');if(saleType==='sale'&&cart.some(l=>l.price<posCost(S.products.find(p=>p.id===l.id)))&&posBelowApproved!==posSignature()){modal='pos-below-cost';render();return false}const costs=new Map(cart.map(l=>[l.id,posCost(S.products.find(p=>p.id===l.id))]));posPreviousPost();if(!cart.length&&view==='invoice'){const r=S.records.find(r=>r.id===selected);r.lines.forEach(l=>l.costAtSale=costs.get(l.product));r.profit=posRound(r.lines.reduce((sum,l)=>sum+(l.price-l.costAtSale)*l.qty,0));S.lastSale=structuredClone(r);posQuery='';posNote='';posBelowApproved='';return true}return false};
act=function(action){const [a,b,c,d]=action.split(':');if(a==='new'&&['sale','purchase'].includes(b)){if(cart.length){posPendingNavigation=action;modal='pos-leave';return render()}posMode='retail';posNote='';posQuery='';posBelowApproved=''}if(['sale','purchase'].includes(view)&&cart.length&&(a==='back'||a==='invoice'||a==='go'&&b!==view)){posPendingNavigation=action;modal='pos-leave';return render()}if(a==='save-product'){const f=form(),edit=modal==='productedit',id=selected,result=posPreviousAct(action);if(modal===null){const p=edit?S.products.find(p=>p.id===id):S.products.at(-1);if(p){if('expiry' in f)p.expiry=f.expiry;if('note' in f)p.note=f.note}if(!edit&&['sale','purchase'].includes(view)){modal='pos-products';render()}}return result}if(a!=='pos')return posPreviousAct(action);if(b==='recent'){modal='pos-recent';return render()}if(b==='resume'){view=saleType;activeTab='operations';modal=null;return render()}if(b==='add')return posAdd(c);if(b==='qty'){const l=cart.find(l=>l.id===Number(c)),p=S.products.find(p=>p.id===Number(c)),qty=posRound(l.qty+Number(d)),problem=posCheckLine(p,qty);if(problem)return posMessage(problem);l.qty=qty;return render()}if(b==='line'){posEditingLine=Number(c);modal='pos-line';return render()}if(b==='save-line'){const f=form(),l=cart.find(l=>l.id===posEditingLine),p=S.products.find(p=>p.id===posEditingLine),qty=Number(f.quantity),price=Number(f.price),problem=posCheckLine(p,qty);if(problem)return posMessage(problem);if(!Number.isFinite(price)||price<=0)return posMessage('أدخل سعرًا صحيحًا أكبر من صفر');l.qty=qty;l.price=price;modal=null;return render()}if(b==='remove'){cart=cart.filter(l=>l.id!==Number(c));return render()}if(b==='products'){posQuery='';posLimit=20;modal='pos-products';return render()}if(b==='more'){posLimit+=20;return render()}if(b==='party'){if(modal==='payment'&&form().account)paymentAccount=Number(form().account);posReturnToPayment=modal==='payment';posPartyQuery='';modal='pos-party';return render()}if(b==='party-pick'){S.saleParty=Number(c)||null;modal=posReturnToPayment?'payment':null;return render()}if(b==='new-party'){modal='pos-new-party';return render()}if(b==='save-party'){const f=form(),name=f.name?.trim();if(!name)return posMessage('أدخل الاسم');const id=Math.max(0,...S.parties.map(p=>p.id))+1;S.parties.push({id,name,phone:f.phone?.trim()||'',type:saleType==='sale'?'customer':'supplier',balance:0});S.opening.parties[id]=0;S.saleParty=id;modal=posReturnToPayment?'payment':null;return render()}if(b==='warehouse'){modal='pos-warehouse';return render()}if(b==='warehouse-pick'){const w=action.slice('pos:warehouse-pick:'.length);if(!S.warehouses.includes(w))return posMessage('المخزن غير موجود');if(editingId&&w!==posOld()?.warehouse)return posMessage('التعديل يبقى في مخزن الفاتورة الأصلية');if(saleType==='sale'&&cart.some(l=>{const p=S.products.find(p=>p.id===l.id),available=(p.stocks[w]||0)+(posOld()?.warehouse===w?posOld().lines.filter(x=>x.product===p.id).reduce((n,x)=>n+x.qty,0):0);return l.qty>available}))return posMessage('بعض البنود غير متوفرة بالكمية المطلوبة في هذا المخزن. عدّلها أولًا.');S.warehouse=w;syncStock();modal=null;return render()}if(b==='mode'){posMode='retail';cart.forEach(l=>l.price=posUnitPrice(S.products.find(p=>p.id===l.id)));posBelowApproved='';return render()}if(b==='checkout'){for(const l of cart){const problem=posCheckLine(S.products.find(p=>p.id===l.id),l.qty);if(problem)return posMessage(problem)}modal='payment';return render()}if(b==='settlement'){const f=form();if(f.account)paymentAccount=Number(f.account);settlement=c==='note'?'note':'paid';modal='payment';return render()}if(b==='barcode'){modal='pos-barcode';return render()}if(b==='find-barcode'){const p=S.products.find(p=>!p.archived&&p.sku===form().code?.trim());if(!p)return posMessage('لم يُعثر على منتج بهذا الباركود');return posAdd(p.id)}if(b==='note'){modal='pos-note';return render()}if(b==='save-note'){posNote=form().note?.trim()||'';modal=null;return render()}if(b==='clear'){modal='pos-clear';return render()}if(b==='confirm-clear'){cart=[];S.saleParty=null;editingId=null;posNote='';posQuery='';posMode='retail';modal=null;return render()}if(b==='confirm-leave'){const target=posPendingNavigation;posPendingNavigation=null;modal=null;if(target?.startsWith('new:')){cart=[];posNote='';posQuery='';posBelowApproved='';posMode='retail';return posPreviousAct(target)}if(target?.startsWith('source:')){cart=[];return sourceDocument(target.split(':')[1])}return posPreviousAct(target||'back')}if(b==='confirm-below-cost'){posBelowApproved=posSignature();return postSale()}};
document.addEventListener('input',event=>{const e=event.target;if(['pos-search','pos-picker-search'].includes(e.id)){posQuery=e.value;posLimit=20;const target=document.querySelector(e.id==='pos-search'?'#pos-search-results':'#pos-picker-results');if(target)target.innerHTML=e.id==='pos-search'&&!posQuery?'':posProductResults(posQuery)}if(e.id==='pos-party-search'){posPartyQuery=e.value;const type=saleType==='sale'?'customer':'supplier';document.querySelector('#pos-party-results').innerHTML=posPartyResults(S.parties.filter(p=>p.type===type&&!p.archived&&searchMatches(p.name+' '+p.phone,posPartyQuery)))}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&['pos-search','pos-picker-search'].includes(event.target.id)){event.preventDefault();const p=S.products.find(p=>!p.archived&&p.sku===event.target.value.trim());if(p)act('pos:add:'+p.id)}});
