 // Report sources follow Offline Conta's committed-period breakdowns.
// Invoice due is the amount posted at issue, not an allocation of later receipts.
const reportNumber31=value=>Number.isFinite(Number(value))?Number(value):0;
const reportRound31=value=>Math.round((value+Number.EPSILON)*100)/100;
const reportAdd31=(list,value)=>reportRound31(list.reduce((n,row)=>n+reportNumber31(value(row)),0));
const reportRecords31=(kind,all=false)=>liveRecords().filter(r=>(!kind||r.kind===kind)&&(all||inPeriod(r)));
const reportCost31=r=>reportRound31(reportNumber31(r.total)-reportNumber31(r.profit));
